-- Every new array passed lib/background-timeline.ts validate() and matched the owner's preview (5168 with its education
-- entries at the start of the stored array, as approved); every new or changed source link was checked.
-- Each row is set only WHERE md5(background_timeline::text) equals the value exported before this was written
-- (backup, off the repo: "Claude outputs/backups/2026-10-31b-background-before.json"), with background_last_checked
-- = 2026-10-31. Needs no code change (columns from 2026-10-24b; the page code is live on main).
-- Guards (RAISE): exactly 19 rows change, all of them these 19; 249 unchanged; 20 MPs with a timeline before and after;
-- each new array equals the file exactly; 236 entries in all afterwards.
-- Undo: 2026-10-31b-UNDO.sql.
\set ON_ERROR_STOP on
BEGIN;
SET LOCAL statement_timeout = '60s';
SET LOCAL lock_timeout = '5s';

DO $$ BEGIN
  IF (SELECT count(*) FROM public.mp_biography WHERE background_timeline IS NOT NULL) <> 20 THEN RAISE EXCEPTION 'expected 20 MPs with a timeline before'; END IF;
END $$;

CREATE TEMP TABLE bt_before ON COMMIT DROP AS
SELECT member_id, md5(to_jsonb(b)::text) AS h FROM public.mp_biography b;

CREATE TEMP TABLE bt_new (member_id integer PRIMARY KEY, old_md5 text NOT NULL, n integer NOT NULL, tl jsonb NOT NULL) ON COMMIT DROP;
