DO $$ BEGIN
  IF (SELECT count(*) FROM public.mp_biography b JOIN bt_new n USING (member_id) WHERE md5(b.background_timeline::text) = n.old_md5) <> 19 THEN
    RAISE EXCEPTION 'a timeline changed since the export (md5 differs)';
  END IF;
END $$;

UPDATE public.mp_biography b SET background_timeline = n.tl, background_last_checked = DATE '2026-10-31'
  FROM bt_new n WHERE b.member_id = n.member_id AND md5(b.background_timeline::text) = n.old_md5;

DO $$
DECLARE
  changed integer;
  changed_outside integer;
  mp249_changed integer;
  matching integer;
  with_timeline integer;
  entry_total integer;
BEGIN
  SELECT count(*) INTO changed FROM public.mp_biography b JOIN bt_before o USING (member_id) WHERE md5(to_jsonb(b)::text) IS DISTINCT FROM o.h;
  SELECT count(*) INTO changed_outside FROM public.mp_biography b JOIN bt_before o USING (member_id)
   WHERE b.member_id NOT IN (SELECT member_id FROM bt_new) AND md5(to_jsonb(b)::text) IS DISTINCT FROM o.h;
  SELECT count(*) INTO mp249_changed FROM public.mp_biography b JOIN bt_before o USING (member_id) WHERE b.member_id = 249 AND md5(to_jsonb(b)::text) IS DISTINCT FROM o.h;
  SELECT count(*) INTO matching FROM public.mp_biography b JOIN bt_new n USING (member_id)
   WHERE b.background_timeline = n.tl AND jsonb_array_length(b.background_timeline) = n.n AND b.background_last_checked = DATE '2026-10-31';
  SELECT count(*) INTO with_timeline FROM public.mp_biography WHERE background_timeline IS NOT NULL;
  SELECT sum(jsonb_array_length(background_timeline)) INTO entry_total FROM public.mp_biography WHERE background_timeline IS NOT NULL;
  RAISE NOTICE 'rows changed %, outside the 19 %, 249 changed %, rows matching the file %, MPs with a timeline %, entries %',
    changed, changed_outside, mp249_changed, matching, with_timeline, entry_total;
  IF changed <> 19 THEN RAISE EXCEPTION 'expected exactly 19 rows changed, got %', changed; END IF;
  IF changed_outside <> 0 THEN RAISE EXCEPTION '% rows outside the 19 changed', changed_outside; END IF;
  IF mp249_changed <> 0 THEN RAISE EXCEPTION 'MP 249 changed'; END IF;
  IF matching <> 19 THEN RAISE EXCEPTION 'expected 19 rows matching the file, got %', matching; END IF;
  IF with_timeline <> 20 THEN RAISE EXCEPTION 'expected 20 MPs with a timeline after, got %', with_timeline; END IF;
  IF entry_total <> 236 THEN RAISE EXCEPTION 'expected 236 entries, got %', entry_total; END IF;
END $$;

COMMIT;
